<script setup lang="ts">
import{onBeforeUnmount,onMounted,ref}from"vue";import{onBeforeRouteLeave,useRoute,useRouter}from"vue-router";import BaseEmptyState from"@/components/base/BaseEmptyState.vue";import BasePageHeader from"@/components/base/BasePageHeader.vue";import TitleForm from"@/features/catalog/components/TitleForm.vue";import type{TitleFormData}from"@/domain/catalog/models";import type{ExistingTitleImages}from"@/domain/catalog/images";import{mapTitleFormToUpdatePayload,mapTitleRecordToForm}from"@/domain/catalog/mapper";import{titleRepository}from"@/domain/repositories";import{pb}from"@/infrastructure/pocketbase/client";import type{TitleRecord}from"@/types/records";
const route=useRoute(),router=useRouter(),id=String(route.params.id);const initialValue=ref<TitleFormData|null>(null),existingImages=ref<ExistingTitleImages>({}),titleName=ref(""),loading=ref(true),saving=ref(false),dirty=ref(false),error=ref("");let allowNavigation=false;
async function load(){loading.value=true;error.value="";try{const r=await titleRepository.get(id)as TitleRecord;initialValue.value=mapTitleRecordToForm(r);titleName.value=initialValue.value.titulo;existingImages.value={poster:r.poster?pb.files.getURL(r,r.poster):"",backdrop:r.backdrop?pb.files.getURL(r,r.backdrop):"",logo:r.logo?pb.files.getURL(r,r.logo):""};dirty.value=false}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
async function save(f:TitleFormData){saving.value=true;error.value="";try{await titleRepository.update(id,mapTitleFormToUpdatePayload(f));allowNavigation=true;dirty.value=false;await router.push({name:"catalog-detail",params:{id},query:{updated:"1"}})}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}
function beforeUnload(e:BeforeUnloadEvent){if(!dirty.value)return;e.preventDefault();e.returnValue=""}onBeforeRouteLeave(()=>allowNavigation||!dirty.value||window.confirm("Existem alterações por guardar. Queres sair sem guardar?"));onMounted(()=>{window.addEventListener("beforeunload",beforeUnload);void load()});onBeforeUnmount(()=>window.removeEventListener("beforeunload",beforeUnload));
</script><template><section v-if="loading" class="page-loading"><span class="loader"/><p>A carregar título…</p></section><BaseEmptyState v-else-if="error&&!initialValue" icon="!" title="Não foi possível abrir o título" :description="error"><button class="button button-secondary" @click="load">Voltar a tentar</button></BaseEmptyState><template v-else-if="initialValue"><BasePageHeader eyebrow="Catálogo" :title="`Editar ${titleName}`" description="Atualiza dados, relações e imagens do título."/><div v-if="error" class="form-alert form-alert-error">{{error}}</div><TitleForm :initial-value="initialValue" :existing-images="existingImages" :saving="saving" submit-label="Guardar alterações" :cancel-to="`/catalogo/${id}`" @dirty-change="dirty=$event" @submit="save"/></template></template>
